//! The engine's generated files: the shipped table the client reads
//! (`crates/uorc/src/weights.rs`, from `model/engine.toml`) and the
//! scheduled workflow (`.github/workflows/engine.yml`, from `Uorc.Engine`).
//! Neither is edited by hand; the tests refuse drift.

use crate::model::Laws;
use crate::space::Portfolio;
use uorc::portfolio;

/// The generated workflow, relative to the repository root.
pub const WORKFLOW: &str = ".github/workflows/engine.yml";

/// The branch a tick proposes its commit on.
pub const BRANCH: &str = "engine/tick";

fn bytes(values: &[u8], per_line: usize, hex: bool) -> String {
    values
        .chunks(per_line)
        .map(|line| {
            let items: Vec<String> = line
                .iter()
                .map(|b| {
                    if hex {
                        format!("0x{b:02x},")
                    } else {
                        format!("{b},")
                    }
                })
                .collect();
            format!("    {}\n", items.join(" "))
        })
        .collect()
}

/// `crates/uorc/src/weights.rs` for `portfolio`.
pub fn weights_rs(portfolio: &Portfolio) -> String {
    let s = portfolio.strategy_bytes();
    let w = portfolio.weight_bytes();
    format!(
        "// @generated by `uorc-engine` from model/engine.toml (Uorc.Engine); do not edit.\n\
         //! The shipped strategy portfolio, as the engine consolidated it.\n\
         \n\
         /// Five bytes per strategy: the u32 little-endian word (bits 0-19 the ncm\n\
         /// profile word, bit 31 the x86 filter), then the state index (0 for none).\n\
         #[rustfmt::skip]\n\
         pub const STRATEGIES: [u8; {}] = [\n{}];\n\
         \n\
         /// One weight in 1..=16 per (family, strategy): byte `family * S + strategy`.\n\
         #[rustfmt::skip]\n\
         pub const WEIGHTS: [u8; {}] = [\n{}];\n",
        s.len(),
        bytes(&s, portfolio::ENTRY, true),
        w.len(),
        bytes(&w, portfolio.entries.len().max(1), false),
    )
}

/// `.github/workflows/engine.yml` under `laws`.
pub fn workflow(laws: &Laws) -> String {
    format!(
        r#"# Generated by `uorc-engine render` from src/Uorc/Engine.lex.tex (crates/engine).
# Do not edit: the engine's tests refuse drift. The kernel decides the facts it
# rests on (Uorc.Engine.shippedWorkflowIsValid): the cron sits off the hour,
# twice an hour, and setup plus the tick fit the job's timeout. No LLM is in
# the loop: each tick mints dominance hypotheses by the rule 30 register and
# the search weights, decides them over the κ-named corpus (a claim known by
# its κ is never rerun), and consolidates the winners into the shipped
# portfolio. A tick that advanced is committed to {branch}, proposed as one
# pull request to main, and the acceptance gate is dispatched on it; main
# changes only when that request merges.
name: engine

on:
  schedule:
    - cron: "{first},{second} * * * *"
  workflow_dispatch:

permissions:
  contents: read

concurrency:
  group: engine
  cancel-in-progress: false

jobs:
  tick:
    name: one tick of the engine
    if: github.repository == 'UOR-Foundation/compression' && vars.UORC_ENGINE != 'off'
    runs-on: ubuntu-24.04
    timeout-minutes: {timeout}
    permissions:
      contents: write
      pull-requests: write
      actions: write
    steps:
      - uses: actions/checkout@11bd71901bbe5b1630ceea73d27597364c9af683
        with:
          fetch-depth: 0
          persist-credentials: false
      - name: Carry the open tick onto main
        run: |
          set -euo pipefail
          git config user.name uorc-engine
          git config user.email uorc-engine@users.noreply.github.com
          if git ls-remote --exit-code origin refs/heads/{branch} >/dev/null; then
            git fetch origin {branch}
            git checkout -B {branch} FETCH_HEAD
            git rebase origin/main || {{ git rebase --abort; git checkout -B {branch} origin/main; }}
          else
            git checkout -B {branch} origin/main
          fi
      - uses: actions/cache@0057852bfaa89a56745cba8c7296529d2fc39830
        with:
          path: target
          key: engine-target-${{{{ hashFiles('Cargo.lock', 'generated/rust/**/provenance.json') }}}}
          restore-keys: engine-target-
      - name: Build the engine
        timeout-minutes: {setup}
        run: cargo build --locked --release -p uorc-engine
      - name: Tick
        id: tick
        timeout-minutes: {tick}
        run: target/release/uorc-engine tick --output "$GITHUB_OUTPUT" --summary .engine-summary.md
      - name: Propose the tick
        if: steps.tick.outputs.outcome != 'settled'
        env:
          GH_TOKEN: ${{{{ github.token }}}}
          TITLE: ${{{{ steps.tick.outputs.title }}}}
        run: |
          set -euo pipefail
          git add frontier.toml model/engine.toml model/hypotheses.toml crates/uorc/src/weights.rs
          git commit -m "$TITLE"
          auth=$(printf 'x-access-token:%s' "$GH_TOKEN" | base64 -w0)
          git -c "http.https://github.com/.extraheader=AUTHORIZATION: basic $auth" push --force origin HEAD:refs/heads/{branch}
          if [ "$(gh pr list --head {branch} --state open --json number --jq length)" = "0" ]; then
            gh pr create --base main --head {branch} --title "$TITLE" --body-file .engine-summary.md
          else
            gh pr edit {branch} --title "$TITLE" --body-file .engine-summary.md
          fi
          gh workflow run bootstrap.yml --ref {branch}
      - name: Tick summary
        if: always()
        run: test -f .engine-summary.md && cat .engine-summary.md >> "$GITHUB_STEP_SUMMARY" || true
"#,
        branch = BRANCH,
        first = laws.cron_first,
        second = laws.cron_second,
        timeout = laws.timeout_minutes,
        setup = laws.setup_minutes,
        tick = laws.tick_minutes,
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::state::EngineFile;
    use std::path::Path;

    fn root() -> std::path::PathBuf {
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
    }

    #[test]
    fn the_shipped_table_is_generated_from_the_engine_state() {
        let laws = Laws::load(&root()).expect("laws");
        let engine = EngineFile::load(&root()).expect("engine.toml");
        let portfolio = Portfolio::of(&engine, &laws).expect("portfolio");
        let committed =
            std::fs::read_to_string(root().join(crate::state::WEIGHTS_RS)).expect("weights.rs");
        assert_eq!(
            committed,
            weights_rs(&portfolio),
            "run `cargo run -p uorc-engine -- render`"
        );
        assert_eq!(
            portfolio.strategy_bytes(),
            uorc::weights::STRATEGIES.to_vec()
        );
        assert_eq!(portfolio.weight_bytes(), uorc::weights::WEIGHTS.to_vec());
    }

    #[test]
    fn the_workflow_is_generated_from_the_model() {
        let laws = Laws::load(&root()).expect("laws");
        assert!(laws.valid_workflow());
        let committed = std::fs::read_to_string(root().join(WORKFLOW)).expect("engine.yml");
        assert_eq!(
            committed,
            workflow(&laws),
            "run `cargo run -p uorc-engine -- render`"
        );
    }
}
